+ '<span class="cm"># 9 labels total</span>\n'
+ 'O                          <span class="cm"># Outside any entity</span>\n'
+ 'B-PER, I-PER               <span class="cm"># Person</span>\n'
+ 'B-ORG, I-ORG               <span class="cm"># Organization</span>\n'
+ 'B-LOC, I-LOC               <span class="cm"># Location</span>\n'
+ 'B-MISC, I-MISC             <span class="cm"># Miscellaneous</span>\n'
+ '\n'
+ '<span class="cm"># Numerical label mapping (model outputs integers)</span>\n'
